from kd_common import *
i=4
Z=lambda q,a:[('z',q),('b',a)]
def ktemple(w=1): return '<rect x="-70" y="-50" width="140" height="50" fill="#e9d6c0"/><path d="M-90 -50 L0 -100 L90 -50z" fill="#7a3b1f"/><path d="M-60 -70 L0 -110 L60 -70" fill="none" stroke="#5a2a10" stroke-width="3"/><rect x="-14" y="-36" width="28" height="36" fill="#5a3a1a"/>'
def rain(): return ''.join(f'<path d="M{x} {y} l-6 14" stroke="#4aa3df" stroke-width="2"/>' for x in range(40,540,36) for y in (20,60,100))
fw=foreword(i,['Below the peak of Tadiyaṇḍamōl, in the forest near Kakkabe, stands the most important temple of the Kodavas: <b>Pāḍi Igguthappa</b>. Igguthappa is the god of <b>rain and rice</b>, and of snakes; he is called the chief guru of Kodagu; and it is at his temple that the date of '+L('/kodagu/puttari/','Puttari')+' is fixed each year.',
 'This part tells the legend of the seven divine siblings, the founding of the temple, its families and its festivals, what is offered and asked of the god, and his place beside '+L('/kodagu/kaveri-sankramana/','Kāverī Amma')+'.',
 'Other gods of the nāḍs are in '+L('/kodagu/village-deities/','Part 9')+' and other temples in '+L('/kodagu/temples/','Part 10')+'.'],Z('Is Igguthappa Śiva?','Some say Śiva, some say Subrahmaṇya. For Kodavas he is simply Igguthappa, their own god.'))
gl=glance([('God','Igguthappa, “Lord of rain and crops”'),('Also','Called the Mahā Guru of Kodagu; linked with snakes'),('Identified with','Subrahmaṇya or Śiva (sources differ)'),('Main temple','Pāḍi Igguthappa, Kakkabe, Napoklu region'),('Distance','About 35 km from Madikeri'),('Legend','One of seven divine siblings who came from Kerala'),('Managers','The Pardanda family, by tradition'),('Annual festival','Kaladcha, in March'),('Puttari','Date fixed here every year'),('Other shrines','Nelji, Peroor and elsewhere')],
 S('A Kerala-style temple on a forested hill with rain clouds',hills(560,120,'#3a7a4a')+g(280,200,1.6,ktemple())+'<ellipse cx="140" cy="40" rx="70" ry="22" fill="#9aa"/><ellipse cx="420" cy="40" rx="70" ry="22" fill="#9aa"/>'+rain(),'#d8e8f0',215),Z('Why rain?','Rain decides the paddy, and paddy decided life in Kodagu.'),'The god <b>of rain and rice</b>.')
seven=story('seven','THE SEVEN','Six brothers and a sister',strip('Three panels: seven children arrive from the west; they part on the hills; Igguthappa settles at Malma hill',
 [('<rect width="144" height="190" fill="#d8e8f0"/>'+''.join(g(16+k*18,180,.45,person(['#c0392b','#1d4f8a','#2a9d6f','#e0a800','#6a3d9a','#8a5a2a','#d36a9a'][k])) for k in range(7)),'#d8e8f0'),
  ('<rect width="144" height="190" fill="#d8e8c8"/>'+hills(144,120,'#5a9a5a')+''.join(g(20+k*20,150+(k%2)*20,.4,person(['#c0392b','#1d4f8a','#2a9d6f','#e0a800','#6a3d9a','#8a5a2a','#d36a9a'][k])) for k in range(7)),'#d8e8c8'),
  ('<rect width="144" height="190" fill="#d8e8c8"/>'+hills(144,110,'#3a7a4a')+g(72,170,.6,ktemple()),'#d8e8c8')],['from the west','parting ways','Malma hill']),'The legend as told in Kodagu; there are slight variations.',
 ['In ancient times seven divine children came from what is now Kerala: six brothers, Igguthappa among them, and one sister.','They chose Kodagu and its borders as their home and parted, each to a place; the sister, <b>Pannaṅgālatamme</b>, settled at her own shrine.','Igguthappa came to <b>Malma</b> hill (Igguthappa beṭṭa) above Pāḍi, and became the chief god of the Kodavas.'])
found=reading('founding','THE TEMPLE','Muthanna and the Pardandas',S('A man building a temple; his family stand beside it',g(330,200,1.6,ktemple())+g(150,210,1.4,kodava_man())+g(200,210,1,kodava_woman()),'#d8e8c8',215),
 ['<b>Muthanna.</b> In the common telling, a man named <b>Muthanna</b> had a temple built for Igguthappa near Malma hill: this became the Pāḍi temple.','<b>Other temples.</b> From Malma the god visited Ammaṅgēri, <b>Nelji</b> and <b>Peroor</b>, where local clans built two more ancient Igguthappa temples.','<b>Managers.</b> Muthanna’s descendants, the <b>Pardanda</b> family, became the hereditary managers (dēva takka) of the temple.','<b>Puttari.</b> The Pardandas, with the astrologers of Ammaṅgēri, take part in fixing the Puttari date (see '+L('/kodagu/puttari/','Part 2')+').','<b>Communities.</b> The Kembaṭṭi community also has old ties to the temple, mentioned in 19th-century Hāleri texts.'],Z('A family runs the temple?','By tradition, yes. Kodagu temples are rooted in clans.'),'A clan <b>keeps the god’s house</b>.')
hist=reading('history','HISTORY','Old shrine, royal patron',svg(560,150,'Timeline of the temple','<rect width="560" height="150" fill="#fff3cf"/>'+tl_strip([('legend','seven siblings'),('1153','traditional date'),('c. 1810','Liṅgarājendra'),('today','renovated')],560,150)),
 ['<b>Old.</b> Tradition dates the temple to <b>1153</b>. (Legendary date.)','<b>The rāja.</b> It rose to prominence under the Hāleri king <b>Liṅgarājendra</b>, who is said to have built or rebuilt it around 1810.','<b>An anecdote.</b> A story tells that in 1811 the king came to the forest to hunt elephants and had an experience of the god. (Anecdote, C. P. Belliappa.)','<b>Rain.</b> Another story tells of a prayer for rain answered within hours.','<b>Today.</b> The temple has been renovated and is run by a temple committee with the hereditary families.'],Z('1153 or 1810?','The shrine is old; the building we see owes much to the 1810s and later repairs.'),'Old in faith, <b>renewed by kings</b>.')
temple=reading('temple','THE BUILDING','A Kerala-style temple',S('A square temple with sloping tiled roof and a long flight of steps',g(280,170,2,ktemple())+'<path d="M240 170 l-30 50 h140 l-30 -50" fill="#9a8a7a"/>'+g(140,215,1.2,tree('#2f6a3a'))+g(440,215,1.2,tree('#3a8a4a')),'#d8e8c8',230),
 ['<b>Style.</b> The temple resembles traditional <b>Kerala</b> temples: square plan, sloping tiled roofs, wooden work.','<b>Approach.</b> A long flight of steps leads up from the base.','<b>Bali pīṭha.</b> An altar stone stands at the entrance.','<b>Woodwork.</b> Carved wood is a feature of the building.','<b>Setting.</b> It sits in forest below the hills of Tadiyaṇḍamōl, Kodagu’s highest peak.'],Z('Why Kerala style?','The siblings came from Kerala, and Kodagu’s temples share that hill-and-rain architecture.'),'A Kerala roof <b>in Kodava forest</b>.')
asks=cards('asks','WHAT PEOPLE ASK','Rain, crops, children, snakes',fig_row('Clouds, paddy, a cradle and a snake',[(rain()[:400],1),(paddy(3,40,30),1.2),('<path d="M-20 0 q20 -20 40 0" stroke="#8a5a2a" stroke-width="5" fill="none"/>',1.2),('<path d="M-20 0 q10 -14 20 0 t20 0" stroke="#2f8a3a" stroke-width="5" fill="none"/><circle cx="22" r="4" fill="#2f8a3a"/>',1.3)],['rain','rice','child','snake'],gy=150),
 [('🌧️','Rain','Farmers pray for timely rain.'),('🌾','Harvest','He is lord of the paddy; Puttari begins with him.'),('👶','Children','Childless couples come to pray; the priest speaks of many blessed.'),('🐍','Snakes','He is linked with snakes, and is prayed to against snake troubles.'),('🍛','Annadāna','Visitors are served a simple lunch daily.'),('🗓️','Dates','Puttari’s day and hour are announced here.')],None,'What the farmer <b>asks of his god</b>.')
kal=reading('kaladcha','KALADCHA','The annual festival in March',S('Devotees carrying the deity up a hill in procession with drums',hills(560,110,'#3a7a4a')+''.join(g(120+k*70,200-k*14,.9,kodava_man()) for k in range(5))+g(470,120,.8,'<rect x="-14" y="-24" width="28" height="24" fill="#e0a800"/>')+g(80,200,1,dudi()),'#d8e8f0',215),
 ['<b>Kaladcha.</b> The temple’s annual festival, <b>Kaladcha</b>, is held in March.','<b>Up the hill.</b> The god is taken in procession up Malma hill and brought back to Pāḍi. (As described.)','<b>Drums and dance.</b> Kodava music and dances accompany the god.','<b>Rules.</b> As before every temple festival in Kodagu, the nāḍ keeps rules for some days beforehand.','<b>Crowds.</b> Kodavas and other communities come from across the district.'],Z('Why carry him up the hill?','Malma is where he first settled. The god goes home and returns.'),'The god <b>visits his first hill</b>.')
put=reading('puttari','PUTTARI AT PĀḌI','The harvest begins here',S('At the temple, the first sheaves are cut by torchlight',g(280,170,1.6,ktemple())+g(150,215,1.2,kodava_man())+g(170,150,.6,flame())+g(420,215,1.2,paddy(4,80,40)),'#20243a',230),
 ['<b>Fixing.</b> The Puttari day and timings are fixed at Pāḍi by astrologers and families.','<b>First.</b> The first harvest rite is performed at the temple before the rest of Kodagu.','<b>Pāḍi poḷd.</b> Old accounts call the temple’s observance <b>Pāḍi poḷd</b>.','<b>Then everywhere.</b> After it the nāḍs and ainmanes cut their own sheaves.','<b>Read.</b> The full festival is in '+L('/kodagu/puttari/','Part 2')+'.'],Z('So nobody harvests before Igguthappa?','In tradition, no. The god eats first.'),'The god <b>harvests first</b>.')
pair=reading('pair','RIVER AND RAIN','Kāverī and Igguthappa',S('A river goddess and a rain god side by side above paddy',g(170,200,1.4,devi(sari='#4aa3df',items=('pot',)))+g(390,200,1.4,god('#2a9d6f'))+rain(),'#d8e8f0',215),
 ['<b>Two deities.</b> Kāverī and Pāḍi Igguthappa are the two presiding deities of Kodagu.','<b>Water both ways.</b> She is the river from below; he is the rain from above.','<b>Mother and guru.</b> She is kuladēvī; he is Mahā Guru.','<b>In songs.</b> Kodava songs praise both together.','<b>Through the year.</b> Kāverī at Saṅkramaṇa, Igguthappa at Puttari and Kaladcha.'],Z('Which is more important?','Ask a Kodava and he will say: both, at different seasons.'),'River from below, <b>rain from above</b>.')
visit=reading('visit','VISITING','Going to Pāḍi',S('A road winding up through coffee to the temple',hills(560,120,'#3a7a4a')+'<path d="M60 230 C200 180 160 130 300 120 S420 90 480 70" stroke="#9a8a7a" stroke-width="8" fill="none"/>'+g(480,80,.7,ktemple())+g(120,210,1,coffee()),'#d8e8c8',215),
 ['<b>Where.</b> About 3 km from Kakkabe and about 35 km from Madikeri.','<b>Dress.</b> Traditional dress rules for men may apply inside; check at the temple.','<b>Lunch.</b> Annadāna is served at midday.','<b>Nearby.</b> Tadiyaṇḍamōl trek and the Nālknāḍ palace.','<b>Respect.</b> It is a living clan temple; follow local custom.'],Z('Can anyone go?','Yes. Dress modestly and follow the rules posted.'),'Up through the coffee <b>to the god</b>.')
endp=end(i,['<b>God.</b> Igguthappa, god of rain, rice and snakes, Mahā Guru of Kodagu.','<b>Legend.</b> Seven divine siblings from Kerala; he settled at Malma hill.','<b>Temple.</b> Pāḍi, near Kakkabe; Kerala style; Pardanda family.','<b>Festivals.</b> Kaladcha in March; Puttari fixed and begun here.'],'Part 6 is the mand and its dances.','Rain from above')
src=sources([('Temple and legend:','Coorg Tourism Info (M. Kushalappa), “Padi Igguthappa temple” (seven siblings, Muthanna, Malma, Nelji, Peroor, Pardanda dēva takka); Deccan Herald (C. P. Belliappa), “At the summit of faith” (1153, Liṅgarājendra, lunch); Wikipedia “Igguthappa” (Kaladcha in March); Inditales (Subrahmaṇya identification, rain, childless couples); Deccan Herald on the Kembaṭṭi community; Trawell (distances).')],'the 1153 date is legendary; the 1810 building date and the hunting anecdote are as told; the identification with Śiva or Subrahmaṇya varies by source; procession details of Kaladcha follow travel accounts.','Kodava names romanised simply.')
finish(i,'PART 5 OF 12 · PĀḌI · RAIN · RICE',covart('A Kerala-style temple on a forested hill under rain clouds',hills(440,100,'#3a7a4a')+g(220,180,1.3,ktemple())+'<ellipse cx="120" cy="40" rx="60" ry="18" fill="#9aa"/><ellipse cx="320" cy="40" rx="60" ry="18" fill="#9aa"/>'),'Rain from above',
 '<b>Igguthappa</b>, the Kodava god of <b>rain and rice</b>: the legend of the seven siblings, the Pāḍi temple near Kakkabe, its families, the Kaladcha festival and the start of Puttari.',
 'Igguthappa and the Pāḍi Igguthappa temple explained and illustrated: seven divine siblings legend, Muthanna and the Pardanda family, history, Kerala-style building, prayers for rain, crops and children, Kaladcha, Puttari, and Kāverī and Igguthappa.',
 [fw,gl,seven,found,hist,temple,asks,kal,put,pair,visit,endp,src])
